// Solution: SentinelCore
// Project:   SentinelCore.Orchestrations
// File:         BlocklistRule.cs
// Author: Kyle L. Crowder
// Build Num:  091418



namespace SentinelCore.Orchestrations.SafetyEngine.Rules;





/// <summary>
///     A safety rule that blocks prompts containing content matching any entry in a
///     configurable blocklist of strings. Matches are case-insensitive by default.
/// </summary>
public sealed class BlocklistRule : ISafetyRule
{
    private static readonly string[] DefaultBlocklist =
    {
            "malicious", "harmful", "exploit", "privilege escalation",
            "explain how to", "how to block", "in the news"
    };

    private readonly IReadOnlyList<string> _blocklist;
    private readonly StringComparison _comparison;
    private readonly SafetySeverity _severity;








    /// <summary>
    ///     Initializes a new <see cref="BlocklistRule" /> with default, predefined threat patterns.
    /// </summary>
    /// <param name="name">The unique name of this rule.</param>
    /// <param name="blocklist">Optional blocklisted terms or phrases to evaluate. When omitted, the built-in defaults are used.</param>
    /// <param name="severity">The severity to assign when a blocklisted term is found.</param>
    /// <param name="description">A description of what this rule checks.</param>
    public BlocklistRule(string name, IEnumerable<string>? blocklist, SafetySeverity severity, string? description = null)
        : this(name, severity, description, blocklist)
    {
    }

    /// <summary>
    ///     Initializes a new <see cref="BlocklistRule" /> with default, predefined threat patterns.
    /// </summary>
    /// <param name="name">The unique name of this rule.</param>
    /// <param name="severity">The severity to assign when a blocklisted term is found.</param>
    /// <param name="description">A description of what this rule checks.</param>
    public BlocklistRule(string name, SafetySeverity severity = SafetySeverity.High, string? description = null)
        : this(name, severity, description, null)
    {
    }

    private BlocklistRule(string name, SafetySeverity severity, string? description, IEnumerable<string>? blocklist)
    {
        ArgumentNullException.ThrowIfNull(name);

        Name = name;
        Severity = severity;
        Description = description ?? "Blocks prompts containing blocklisted terms or phrases.";
        _comparison = StringComparison.OrdinalIgnoreCase;

        IEnumerable<string> effectiveBlocklist = blocklist ?? DefaultBlocklist;
        string[] normalizedBlocklist = effectiveBlocklist
                .Where(term => !string.IsNullOrWhiteSpace(term))
                .Select(term => term.Trim())
                .ToArray();

        _blocklist = normalizedBlocklist.Length > 0 ? normalizedBlocklist : DefaultBlocklist;
    }








    public string Description { get; }








    public Task<SafetyRuleResult> EvaluateAsync(SafetyEvaluationContext context, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(context);

        string text = context.CombinedText;

        foreach (string term in _blocklist)
            if (text.Contains(term, _comparison))
            {
                return Task.FromResult(SafetyRuleResult.Block(Name, _severity, "Prompt contains blocklisted term."));
            }

        return Task.FromResult(SafetyRuleResult.Allow(Name));
    }








    public string Name { get; }
    public SafetySeverity Severity { get; private set; }
}

