using System.Collections.Generic;
using SentinelCore.Domain.Contracts;

/// <summary>
/// Holds the result of a single safety rule evaluation run, contributing to the global score.
/// </summary>
public class SafetyRuleEvaluationResult
{
    /// <summary>
    /// The calculated weighted score contribution from this specific rule.
    /// </summary>
    public double Score { get; init; } = 0.0;

    /// <summary>
    /// True if this rule found terms that require immediate, mandatory review (Highest Priority Block).
    /// This overrides all score calculations.
    /// </summary>
    public bool RequiresImmediateReview { get; init; } = false;

    /// <summary>
    /// A list of indicators that contributed to the score.
    /// </summary>
    public List<SafetyIndicator> MatchedIndicators { get; init; } = new List<SafetyIndicator>();

    /// <summary>
    /// Optional message detailing why the rule was triggered.
    /// </summary>
    public string FailureReason { get; init; } = null;
}

using System.Collections.Generic;
using SentinelCore.Domain.Contracts;

/// <summary>
/// Provides a read-only snapshot of the safety context for a single turn,
/// used by all safety rules to contribute to the final score.
/// </summary>
public class GlobalSafetyContext
{
    /// <summary>
    /// The cumulative weighted score calculated across all rules for this turn.
    /// </summary>
    public double CurrentScore { get; private set; } = 0.0;

    /// <summary>
    /// The overall highest-priority immediate block signal found in this turn.
    /// </summary>
    public bool OverallImmediateBlockRequired { get; private set; } = false;

    /// <summary>
    /// History of all safety rule results for tracing and logging.
    /// </summary>
    public List<SafetyRuleEvaluationResult> History { get; } = new List<SafetyRuleEvaluationResult>();

    /// <summary>
    /// The original input prompt text.
    /// </summary>
    public string OriginalPrompt { get; }

    public GlobalSafetyContext(string originalPrompt)
    {
        OriginalPrompt = originalPrompt;
    }

    /// <summary>
    /// Updates the context with a new rule evaluation result.
    /// </summary>
    public void IncorporateResult(SafetyRuleEvaluationResult result)
    {
        this.CurrentScore += result.Score;
        this.History.Add(result);

        // Critical check: If any rule triggers an immediate block, the whole context is flagged.
        if (result.RequiresImmediateReview)
        {
            this.OverallImmediateBlockRequired = true;
        }
    }
}

// SafetyImmediateBlockException.cs
using System;

public class SafetyImmediateBlockException : Exception
{
    public SafetyImmediateBlockException(string message) : base(message) { }
}

// SafetyEngineInternalException.cs
using System;
using System.Collections.Generic;

public class SafetyEngineInternalException : Exception
{
    public Dictionary<string, object> ContextData { get; } = new Dictionary<string, object>();

    public SafetyEngineInternalException(string message, Exception innerException) : base(message, innerException) { }

    /// <summary>
    /// Populates the exception with detailed tracing information for monitoring.
    /// </summary>
    public void AddContext(string key, object value)
    {
        ContextData[key] = value;
    }
}

