/// </summary>
public sealed class BlocklistRule : ISafetyRule
{
    private readonly IReadOnlyList<SafetyIndicator> _indicators;
    private readonly StringComparison _comparison = StringComparison.OrdinalIgnoreCase;

    /// <summary>
