    public BlocklistRule(string name, SafetySeverity severity = SafetySeverity.High, string? description = null)
        : this(name, GetAllIndicators(), severity, description)
    {
    }

    /// <summary>
    ///     Initializes a new <see cref="BlocklistRule" /> with explicit indicators.
    /// </summary>
    /// <param name="name">The unique name of this rule.</param>
    /// <param name="indicators">Optional indicators to evaluate. When omitted, the built-in defaults are used.</param>
    /// <param name="severity">The severity to assign when a blocklisted term is found.</param>
    /// <param name="description">A description of what this rule checks.</param>
    public BlocklistRule(string name, IEnumerable<SafetyIndicator> indicators, SafetySeverity severity = SafetySeverity.High, string? description = null)
        : this(name, indicators?.Select(indicator => indicator.Term), severity, description)
    {
        _indicators = NormalizeIndicators(indicators);
    }

