    ///     Initializes a new <see cref="BlocklistRule" /> with explicit string blocklist terms.
    ///     Kept for compatibility with existing tests and callers.
    /// </summary>
    public BlocklistRule(string name, IEnumerable<string> blocklist, SafetySeverity severity = SafetySeverity.High, string? description = null)
        : this(name, NormalizeStringsToIndicators(blocklist), severity, description)
